//! Local crash capture and opt-in anonymous diagnostics (#171).
//!
//! Everything in this module runs on the device first. A panic, a startup
//! failure or a failed Tauri command is redacted with
//! [`ludex_core::redact`] and stored in `{appDataDir}/diagnostics.json`; no
//! report leaves the machine until the user explicitly presses "Send" in
//! Settings → Help and about, and sending is refused while the opt-in toggle
//! is off.
//!
//! The install id is a random UUID generated locally. It is not derived from
//! hardware, the account or the hostname, and it can be regenerated by turning
//! the feature off and on again (which also clears the local queue).

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use tauri::{AppHandle, Manager};

use crate::settings::{LocalSettings, UpdateChannel};
use crate::state::AppState;

/// Maximum number of reports kept locally.
pub const MAX_LOCAL_REPORTS: usize = 20;
/// Maximum length of a stored summary.
const MAX_SUMMARY_CHARS: usize = 2_000;
/// Maximum length of a stored stack trace.
const MAX_STACK_CHARS: usize = 6_000;
/// Maximum number of log lines kept per report.
const MAX_LOG_LINES: usize = 50;
/// Maximum length of one log line.
const MAX_LOG_CHARS: usize = 500;

/// One redacted report stored locally.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct StoredReport {
    /// Local id (a UUID); not sent to the server.
    pub id: String,
    /// Capture time, RFC 3339 UTC.
    pub created_at: String,
    /// `panic`, `startup`, `command`, `install`, `launch`, `update` or `other`.
    pub kind: String,
    /// Redacted one-line summary.
    pub summary: String,
    /// Redacted stack trace, when one was captured.
    pub stack: Option<String>,
    /// Redacted log lines that preceded the failure.
    pub logs: Vec<String>,
    /// Game id when the failure happened for one game.
    pub game_id: Option<i64>,
    /// Game title, redacted, when the failure happened for one game.
    pub game_title: Option<String>,
    /// Tauri command that failed.
    pub command: Option<String>,
    /// True once the user sent this report.
    pub sent: bool,
}

impl Default for StoredReport {
    fn default() -> Self {
        Self {
            id: String::new(),
            created_at: String::new(),
            kind: "other".to_string(),
            summary: String::new(),
            stack: None,
            logs: Vec::new(),
            game_id: None,
            game_title: None,
            command: None,
            sent: false,
        }
    }
}

/// Summary shown by the Settings panel and the crash banner.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ReportSummary {
    /// Local id.
    pub id: String,
    /// Capture time.
    pub created_at: String,
    /// Error kind.
    pub kind: String,
    /// Redacted summary.
    pub summary: String,
    /// Whether the user already sent it.
    pub sent: bool,
}

/// Exact payload the next send would use.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DiagnosticsPreview {
    /// Local report id the payload belongs to.
    pub report_id: String,
    /// The JSON body `POST /api/diagnostics` receives.
    pub payload: Value,
}

/// Everything Settings → Help and about needs about local diagnostics.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DiagnosticsStatus {
    /// Opt-in toggle, always default false.
    pub enabled: bool,
    /// Random install id (generated locally on first read).
    pub install_id: String,
    /// Desktop app version.
    pub app_version: String,
    /// `linux`, `windows`, `macos` or `other`.
    pub platform: String,
    /// Operating system label.
    pub os: String,
    /// UI locale mirrored from the web app.
    pub locale: String,
    /// Update channel.
    pub channel: String,
    /// Local reports, newest first.
    pub reports: Vec<ReportSummary>,
    /// Number of reports not sent yet.
    pub unsent: usize,
    /// Redacted download jobs (#212): last error, attempt, offset and HTTP
    /// status. Never contains a token; empty when no job is tracked.
    pub downloads: Vec<DownloadJobDiagnostics>,
}

/// Redacted snapshot of one download job for the diagnostics bundle (#212).
///
/// The point is to answer "why did this install stop?" from a user's report
/// without asking them to paste logs: the attempt counter, the resume offset,
/// the HTTP status and the last transport error identify the failing layer.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct DownloadJobDiagnostics {
    pub job_id: String,
    pub game_id: i64,
    pub phase: String,
    pub stream: bool,
    /// Connection attempt of the job when the snapshot was taken.
    pub attempt: u32,
    /// Bytes already on disk: the offset the next request resumes from.
    pub offset: u64,
    pub bytes_total: Option<u64>,
    /// HTTP status of the last response, `None` for a pure transport error.
    pub http_status: Option<u16>,
    /// Redacted last transport error.
    pub last_error: Option<String>,
    pub next_retry_at: Option<String>,
    pub waiting_for_network: bool,
}

/// Outcome of an explicit send.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SendOutcome {
    /// Local report id.
    pub report_id: String,
    /// Always true on success; the UI shows a confirmation.
    pub sent: bool,
}

/// Local report store, shared by the Tauri commands and the panic hook.
pub struct DiagnosticsStore {
    path: Option<PathBuf>,
    reports: Mutex<Vec<StoredReport>>,
    redaction: ludex_core::redact::RedactionContext,
}

impl DiagnosticsStore {
    /// Loads the store from `path` (or starts empty when the file is missing
    /// or unreadable).
    pub fn new(path: Option<PathBuf>, redaction: ludex_core::redact::RedactionContext) -> Self {
        let reports = path
            .as_deref()
            .and_then(|path| fs::read(path).ok())
            .and_then(|bytes| serde_json::from_slice::<Vec<StoredReport>>(&bytes).ok())
            .unwrap_or_default();
        Self {
            path,
            reports: Mutex::new(reports.into_iter().take(MAX_LOCAL_REPORTS).collect()),
            redaction,
        }
    }

    /// In-memory store used by tests.
    #[cfg(test)]
    pub fn in_memory() -> Self {
        Self::new(None, test_context())
    }

    /// Redacts and appends one report, then persists the bounded queue.
    #[allow(clippy::too_many_arguments)]
    pub fn record(
        &self,
        kind: &str,
        summary: &str,
        game_id: Option<i64>,
        game_title: Option<&str>,
        command: Option<&str>,
        stack: Option<&str>,
        logs: &[String],
    ) {
        let report = StoredReport {
            id: uuid::Uuid::new_v4().simple().to_string(),
            created_at: crate::util::now_rfc3339(),
            kind: kind.to_string(),
            summary: truncate(
                &ludex_core::redact::redact(summary, &self.redaction),
                MAX_SUMMARY_CHARS,
            ),
            stack: stack.map(|value| {
                truncate(
                    &ludex_core::redact::redact(value, &self.redaction),
                    MAX_STACK_CHARS,
                )
            }),
            logs: logs
                .iter()
                .take(MAX_LOG_LINES)
                .map(|line| {
                    truncate(
                        &ludex_core::redact::redact(line, &self.redaction),
                        MAX_LOG_CHARS,
                    )
                })
                .collect(),
            game_id,
            game_title: game_title
                .map(|value| truncate(&ludex_core::redact::redact(value, &self.redaction), 200)),
            command: command
                .map(|value| truncate(&ludex_core::redact::redact(value, &self.redaction), 120)),
            sent: false,
        };
        let mut reports = self
            .reports
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        reports.insert(0, report);
        reports.truncate(MAX_LOCAL_REPORTS);
        drop(reports);
        self.persist();
    }

    /// Everything Settings → Help and about needs.
    pub fn status(&self, settings: &LocalSettings) -> DiagnosticsStatus {
        DiagnosticsStatus {
            enabled: settings.diagnostics_enabled,
            install_id: settings.diagnostics_install_id.clone(),
            app_version: env!("CARGO_PKG_VERSION").to_string(),
            platform: platform().to_string(),
            os: os_label(),
            locale: settings.ui_language.clone(),
            channel: channel(settings.update_channel).to_string(),
            reports: self.summaries(),
            unsent: self.unsent(),
            downloads: Vec::new(),
        }
    }

    /// Redacted download rows for the diagnostics bundle (#212).
    ///
    /// Tokens live in the job parameters, never in these fields; the error
    /// text is run through the same redaction as a crash report, and the
    /// snapshot is capped at 10 rows (active jobs are the interesting ones).
    pub fn download_jobs(
        &self,
        jobs: impl IntoIterator<Item = crate::install::InstallJob>,
    ) -> Vec<DownloadJobDiagnostics> {
        jobs.into_iter()
            .take(10)
            .map(|job| DownloadJobDiagnostics {
                job_id: job.job_id,
                game_id: job.game_id,
                phase: job.phase.as_str().to_string(),
                stream: job.stream,
                attempt: job.attempt,
                offset: job.bytes_done,
                bytes_total: job.bytes_total,
                http_status: job.http_status,
                last_error: job.last_error.map(|value| {
                    truncate(
                        &ludex_core::redact::redact(&value, &self.redaction),
                        MAX_LOG_CHARS,
                    )
                }),
                next_retry_at: job.next_retry_at,
                waiting_for_network: job.waiting_for_network,
            })
            .collect()
    }

    /// Local reports, newest first.
    pub fn summaries(&self) -> Vec<ReportSummary> {
        self.reports
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .iter()
            .map(|report| ReportSummary {
                id: report.id.clone(),
                created_at: report.created_at.clone(),
                kind: report.kind.clone(),
                summary: report.summary.clone(),
                sent: report.sent,
            })
            .collect()
    }

    /// Number of reports the user has not sent yet.
    pub fn unsent(&self) -> usize {
        self.reports
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .iter()
            .filter(|report| !report.sent)
            .count()
    }

    /// Deletes every stored report (turning the toggle off also calls this).
    pub fn delete_all(&self) {
        self.reports
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .clear();
        self.persist();
    }

    /// Builds the exact JSON body for one report.
    pub fn preview(
        &self,
        settings: &LocalSettings,
        report_id: Option<&str>,
    ) -> Result<DiagnosticsPreview, String> {
        let reports = self
            .reports
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let report = match report_id {
            Some(id) => reports
                .iter()
                .find(|report| report.id == id)
                .ok_or_else(|| "That report is no longer stored locally.".to_string())?,
            None => reports
                .first()
                .ok_or_else(|| "There is no local report to preview yet.".to_string())?,
        };
        Ok(DiagnosticsPreview {
            report_id: report.id.clone(),
            payload: payload(settings, report),
        })
    }

    /// Explicitly sends one report. Refused while the opt-in toggle is off.
    pub async fn send(
        &self,
        client: &reqwest::Client,
        server_url: &str,
        settings: &LocalSettings,
        report_id: &str,
    ) -> Result<SendOutcome, String> {
        ensure_consent(settings)?;
        let server_url = server_url.trim().trim_end_matches('/');
        if server_url.is_empty() {
            return Err(
                "Start the Ludex server (or configure a server URL) before sending a report."
                    .to_string(),
            );
        }
        let preview = self.preview(settings, Some(report_id))?;
        let response = client
            .post(format!("{server_url}/api/diagnostics"))
            .timeout(std::time::Duration::from_secs(20))
            .json(&preview.payload)
            .send()
            .await
            .map_err(|error| format!("Could not reach the server: {error}"))?;
        if !response.status().is_success() {
            return Err(format!(
                "The server rejected the report (HTTP {}).",
                response.status().as_u16()
            ));
        }
        let mut reports = self
            .reports
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(report) = reports.iter_mut().find(|report| report.id == report_id) {
            report.sent = true;
        }
        drop(reports);
        self.persist();
        Ok(SendOutcome {
            report_id: report_id.to_string(),
            sent: true,
        })
    }

    fn persist(&self) {
        let Some(path) = &self.path else {
            return;
        };
        let reports = self
            .reports
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let Ok(bytes) = serde_json::to_vec_pretty(&*reports) else {
            return;
        };
        if let Some(parent) = path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        if let Err(error) = fs::write(path, bytes) {
            tracing::warn!(error = %error, "could not persist the local diagnostics queue");
        }
    }
}

/// Refuses to send while diagnostics are off.
pub fn ensure_consent(settings: &LocalSettings) -> Result<(), String> {
    if settings.diagnostics_enabled {
        Ok(())
    } else {
        Err(
            "Anonymous diagnostics are off. Turn them on first; nothing is sent automatically."
                .to_string(),
        )
    }
}

/// Builds the payload exactly as shown in the preview.
fn payload(settings: &LocalSettings, report: &StoredReport) -> Value {
    json!({
        "installId": settings.diagnostics_install_id,
        "appVersion": env!("CARGO_PKG_VERSION"),
        "platform": platform(),
        "os": os_label(),
        "locale": settings.ui_language,
        "channel": channel(settings.update_channel),
        "errorKind": normalize_kind(&report.kind),
        "summary": report.summary,
        "detail": {
            "command": report.command,
            "gameId": report.game_id,
            "gameTitle": report.game_title,
            "stack": report.stack,
            "logs": report.logs,
        },
    })
}

fn platform() -> &'static str {
    match std::env::consts::OS {
        "linux" => "linux",
        "windows" => "windows",
        "macos" => "macos",
        _ => "other",
    }
}

fn os_label() -> String {
    let name = sysinfo::System::long_os_version()
        .or_else(|_| sysinfo::System::os_version())
        .unwrap_or_else(|_| std::env::consts::OS.to_string());
    format!("{name} ({})", std::env::consts::ARCH)
}

fn channel(channel: UpdateChannel) -> &'static str {
    match channel {
        UpdateChannel::Stable => "stable",
        UpdateChannel::Early => "early",
    }
}

fn normalize_kind(kind: &str) -> &'static str {
    match kind {
        "panic" => "panic",
        "startup" => "startup",
        "command" => "command",
        "api" => "api",
        "install" => "install",
        "launch" => "launch",
        "update" => "update",
        "web" => "web",
        _ => "other",
    }
}

fn truncate(value: &str, max: usize) -> String {
    if value.chars().count() <= max {
        return value.to_string();
    }
    let mut text: String = value.chars().take(max).collect();
    text.push('…');
    text
}

/// Builds the redaction context from the local environment.
pub fn local_redaction_context(server_urls: Vec<String>) -> ludex_core::redact::RedactionContext {
    let home = std::env::var_os("HOME")
        .or_else(|| std::env::var_os("USERPROFILE"))
        .map(|value| value.to_string_lossy().to_string());
    let username = std::env::var("USER")
        .or_else(|_| std::env::var("USERNAME"))
        .ok();
    let hostname = sysinfo::System::host_name().ok();
    let mut context = ludex_core::redact::RedactionContext::new();
    if let Some(home) = home {
        context = context.with_home(home);
    }
    if let Some(username) = username {
        context = context.with_username(username);
    }
    if let Some(hostname) = hostname {
        context = context.with_hostname(hostname);
    }
    for url in server_urls {
        context = context.with_server_url(url);
    }
    context
}

/// Store path inside the app data folder.
#[must_use]
pub fn store_path(app_data: &Path) -> PathBuf {
    app_data.join("diagnostics.json")
}

/// Installs the panic hook once, chaining to the previous hook.
pub fn install_panic_hook(app: AppHandle) {
    let previous = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        if let Some(state) = app.try_state::<AppState>() {
            let location = info
                .location()
                .map(|location| format!("{}:{}", location.file(), location.line()))
                .unwrap_or_else(|| "unknown location".to_string());
            let message = panic_message(info);
            let backtrace = std::backtrace::Backtrace::force_capture().to_string();
            state.diagnostics.record(
                "panic",
                &format!("panic at {location}: {message}"),
                None,
                None,
                None,
                Some(&backtrace),
                &[],
            );
        }
        previous(info);
    }));
}

fn panic_message(info: &std::panic::PanicHookInfo<'_>) -> String {
    if let Some(message) = info.payload().downcast_ref::<&str>() {
        (*message).to_string()
    } else if let Some(message) = info.payload().downcast_ref::<String>() {
        message.clone()
    } else {
        "non-string panic payload".to_string()
    }
}

/// Records a startup failure even when [`AppState`] could not be built.
pub fn record_startup_failure(app: &AppHandle, message: &str) {
    if let Some(state) = app.try_state::<AppState>() {
        state
            .diagnostics
            .record("startup", message, None, None, None, None, &[]);
        return;
    }
    let Ok(app_data) = app.path().app_data_dir() else {
        return;
    };
    let server_url = std::env::var("LUDEX_SERVER_URL").ok().into_iter().collect();
    let store = DiagnosticsStore::new(
        Some(store_path(&app_data)),
        local_redaction_context(server_url),
    );
    store.record("startup", message, None, None, None, None, &[]);
}

#[cfg(test)]
fn test_context() -> ludex_core::redact::RedactionContext {
    ludex_core::redact::RedactionContext::new()
        .with_home("/home/tester")
        .with_username("tester")
        .with_hostname("test-pc")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::settings::LocalSettings;

    fn enabled_settings() -> LocalSettings {
        LocalSettings {
            diagnostics_enabled: true,
            diagnostics_install_id: "install1234567890".to_string(),
            ..LocalSettings::default()
        }
    }

    #[test]
    fn reports_are_redacted_before_storage() {
        let store = DiagnosticsStore::in_memory();
        store.record(
            "command",
            "install_game failed in /home/tester/Games/Hades: token=abcdef123456",
            Some(7),
            Some("Hades"),
            Some("install_game"),
            Some("at /home/tester/ludex/src/install.rs:42"),
            &["GET http://10.1.20.5:8080/api/games".to_string()],
        );
        let reports = store.summaries();
        assert_eq!(reports.len(), 1);
        let summary = &reports[0].summary;
        assert!(!summary.contains("/home/tester"), "{summary}");
        assert!(!summary.contains("abcdef123456"), "{summary}");
        let preview = store
            .preview(&enabled_settings(), Some(&reports[0].id))
            .expect("preview");
        let text = preview.payload.to_string();
        assert!(!text.contains("10.1.20.5"), "{text}");
        assert!(!text.contains("/home/tester"), "{text}");
    }

    #[test]
    fn send_is_refused_without_consent() {
        let store = DiagnosticsStore::in_memory();
        store.record("panic", "boom", None, None, None, None, &[]);
        let settings = LocalSettings::default();
        assert!(!settings.diagnostics_enabled);
        assert!(ensure_consent(&settings).is_err());
        assert_eq!(store.unsent(), 1);
    }

    #[tokio::test]
    async fn send_without_consent_never_touches_the_network() {
        let store = DiagnosticsStore::in_memory();
        store.record("panic", "boom", None, None, None, None, &[]);
        let id = store.summaries()[0].id.clone();
        let settings = LocalSettings::default();
        let client = reqwest::Client::new();
        // Port 1 is refused immediately; reaching it would be a network error
        // instead of the consent error asserted here.
        let error = store
            .send(&client, "http://127.0.0.1:1", &settings, &id)
            .await
            .expect_err("consent gate");
        assert!(error.contains("off"), "{error}");
    }

    #[test]
    fn preview_uses_the_random_install_id_and_version() {
        let store = DiagnosticsStore::in_memory();
        store.record(
            "startup",
            "could not open the database",
            None,
            None,
            None,
            None,
            &[],
        );
        let settings = enabled_settings();
        let preview = store.preview(&settings, None).expect("preview");
        assert_eq!(preview.payload["installId"], "install1234567890");
        assert_eq!(preview.payload["appVersion"], env!("CARGO_PKG_VERSION"));
        assert_eq!(preview.payload["errorKind"], "startup");
    }

    #[test]
    fn the_download_bundle_carries_status_attempt_and_offset_without_tokens() {
        let store = DiagnosticsStore::in_memory();
        let job = crate::install::InstallJob {
            job_id: "job-42".to_string(),
            game_id: 7,
            version_id: 9,
            phase: crate::install::InstallPhase::Downloading,
            bytes_done: 4096,
            bytes_total: Some(8192),
            speed_bps: 0,
            message: Some("Retrying".to_string()),
            install_path: Some("/home/tester/Games/Hades".to_string()),
            stream: true,
            resumable: true,
            entries_done: Some(3),
            entries_total: Some(9),
            current_entry: Some("Game/big.bin".to_string()),
            resumed_entries: None,
            reconnecting: true,
            attempt: 7,
            last_error: Some(
                "Download failed with HTTP 524 for /home/tester/Games/Hades (token=abcdef123456)"
                    .to_string(),
            ),
            stalled_for_ms: None,
            next_retry_at: Some("2026-11-13T02:00:00+00:00".to_string()),
            http_status: Some(524),
            waiting_for_network: false,
            queue_position: None,
        };
        let rows = store.download_jobs(vec![job]);
        assert_eq!(rows.len(), 1);
        let row = &rows[0];
        assert_eq!(row.job_id, "job-42");
        assert_eq!(row.attempt, 7);
        assert_eq!(row.offset, 4096, "the offset is what a resume asks for");
        assert_eq!(row.http_status, Some(524));
        assert_eq!(
            row.next_retry_at.as_deref(),
            Some("2026-11-13T02:00:00+00:00")
        );
        assert!(row.stream);
        let error = row.last_error.as_deref().unwrap_or_default();
        assert!(error.contains("524"), "{error}");
        assert!(!error.contains("abcdef123456"), "token leaked: {error}");
        assert!(!error.contains("/home/tester"), "path leaked: {error}");
        assert!(error.contains("<token>"), "{error}");
    }

    #[test]
    fn deleting_reports_clears_the_queue() {
        let store = DiagnosticsStore::in_memory();
        store.record("panic", "one", None, None, None, None, &[]);
        store.record("panic", "two", None, None, None, None, &[]);
        assert_eq!(store.summaries().len(), 2);
        store.delete_all();
        assert!(store.summaries().is_empty());
        assert!(store.preview(&enabled_settings(), None).is_err());
    }

    #[test]
    fn the_local_queue_is_bounded() {
        let store = DiagnosticsStore::in_memory();
        for index in 0..(MAX_LOCAL_REPORTS + 5) {
            store.record(
                "command",
                &format!("failure {index}"),
                None,
                None,
                None,
                None,
                &[],
            );
        }
        assert_eq!(store.summaries().len(), MAX_LOCAL_REPORTS);
        assert_eq!(store.summaries()[0].summary, "failure 24");
    }
}
